diff --git a/src/main/java/com/networknt/schema/format/TimeFormat.java b/src/main/java/com/networknt/schema/format/TimeFormat.java
index 7b539b9e..cb49da92 100644
--- a/src/main/java/com/networknt/schema/format/TimeFormat.java
+++ b/src/main/java/com/networknt/schema/format/TimeFormat.java
@@ -53,2 +53,11 @@ public class TimeFormat implements Format {
-            TemporalAccessor accessor = formatter.parseUnresolved(value, new ParsePosition(0));
-            if (null == accessor) return false;
+            ParsePosition position = new ParsePosition(0);
+            TemporalAccessor accessor = formatter.parseUnresolved(value, position);
+            // parseUnresolved stops at the end of the pattern, so trailing text must be rejected here
+            if (null == accessor || position.getIndex() != value.length()) return false;
+
+            char last = value.charAt(value.length() - 1);
+            if (last != 'Z' && last != 'z') {
+                // A numeric offset is exactly +HH:MM or -HH:MM. Java 8 also accepts +HH:MM:SS.
+                char sign = value.charAt(value.length() - 6);
+                if (sign != '+' && sign != '-') return false;
+            }
